/* From Uiverse.io by Adamsco51  - Tags: simple, input, click */
.__UIV_SCOPE__ .container {
  width: 300px;
  height: 40px;
  background: #000;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 16px;
  padding: 2px;
}

.__UIV_SCOPE__ .input {
  flex: 1;
  width: 100%;
  height: 100%;
  border: none;
  outline: none;
  padding-left: 55px;
  padding-right: 65px;
  border-radius: 12px;
  background: transparent;
  overflow: hidden;
  font-size: 1.25rem;
  color: #dedede;
  font-weight: 500;
  font-family: "Lucida Sans", "Lucida Sans Regular", "Lucida Grande",
    "Lucida Sans Unicode", Geneva, Verdana, sans-serif;
}

.__UIV_SCOPE__ .search {
  position: absolute;
  left: 0;
  margin: 0 12px;
  z-index: 99;
  stroke: #fff;
}

.__UIV_SCOPE__ .icon {
  width: 32px;
  height: 32px;
  color: #fff;
  cursor: pointer;
}

.__UIV_SCOPE__ button {
  position: absolute;
  backdrop-filter: blur(8px);
  background: transparent;
  background-clip: border-box;
  border: 1px solid #fff;
  border-radius: 8px;
  padding: 2px;
  right: 0;
  margin-right: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .container::before {
  content: "";
  position: absolute;
  left: -25px;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: rgb(202, 241, 61);
  z-index: -1;
  opacity: 0.1;
}

.__UIV_SCOPE__ .container::after {
  content: "";
  position: absolute;
  right: -25px;
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: rgb(202, 241, 61);
  z-index: -1;
  opacity: 0.1;
}
